/* Builds the library as one IIFE (global `Neurosym`) and embeds it at the top of the single inline
   <script> of ../fox-hounds-harness.html, between two markers. The harness stays ONE file.
     node scripts/harness-bundle.mjs          -> rebuild and embed
     node scripts/harness-bundle.mjs --check  -> exit 1 if the embedded bundle is stale */
import { build } from 'esbuild';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const lib = path.resolve(here, '..');
const htmlPath = path.resolve(lib, '..', 'fox-hounds-harness.html');
export const BEGIN = '/* NEUROSYM BUNDLE BEGIN - generated by lib/scripts/harness-bundle.mjs, do not edit */';
export const END = '/* NEUROSYM BUNDLE END */';

export async function bundleText() {
  const result = await build({
    entryPoints: [path.join(lib, 'src', 'browser.ts')],
    absWorkingDir: lib, bundle: true, write: false, format: 'iife', globalName: 'Neurosym',
    target: 'es2020', platform: 'browser', legalComments: 'none', charset: 'utf8'
  });
  return result.outputFiles[0].text.replace(/\r?\n/g, '\r\n');
}

export function embed(html, bundle) {
  const block = BEGIN + '\r\n' + bundle + END;
  const start = html.indexOf(BEGIN);
  if (start >= 0) {
    const stop = html.indexOf(END, start);
    if (stop < 0) throw new Error('bundle BEGIN marker without END marker');
    return html.slice(0, start) + block + html.slice(stop + END.length);
  }
  const open = html.indexOf('<script>');
  if (open < 0) throw new Error('no <script> in the harness');
  const at = html.indexOf('\n', open) + 1;
  return html.slice(0, at) + block + '\r\n' + html.slice(at);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const html = fs.readFileSync(htmlPath, 'utf8');
  const next = embed(html, await bundleText());
  if (process.argv.includes('--check')) {
    if (next !== html) { console.error('STALE: the harness embeds an old bundle; run node scripts/harness-bundle.mjs'); process.exit(1); }
    console.log('OK: the embedded bundle matches lib/src');
  } else {
    fs.writeFileSync(htmlPath, next);
    console.log('embedded ' + (next.length - html.length >= 0 ? '+' : '') + (next.length - html.length) + ' chars into ' + path.basename(htmlPath));
  }
}
